slides=[]
def add(layout,title,**kw):
    slides.append(dict(layout=layout,title=title,**kw))
def cards(title,*items,note='',kicker='',layout='cards',**kw):
    add(layout,title,items=[dict(label=a,text=b) for a,b in items],note=note,kicker=kicker,**kw)
def task(title,question,*steps,note='',number='À VOUS'):
    add('exercise',title,question=question,steps=list(steps),note=note,number=number)
def recap(title,*items,note='Une explication + une exécution + une trace conservée.'):
    cards(title,*items,note=note,kicker='À CE STADE, JE SAIS…')
